<template><section class="wiki-catalog"><div class="catalog-toolbar"><label class="catalog-search"><span>{{en?'Search':'搜索'}}</span><input v-model="search" :placeholder="en?'Name, ID, or in-game description':'输入名称、ID 或游戏内说明'" type="search" @input="page=1" /></label><label>{{en?'Category':'分类'}}<select v-model="filter" @change="page=1"><option value="all">{{categoryNames[lc].all}}</option><option v-for="category in categories" :key="category" :value="category">{{categoryNames[lc][category]||category}}</option></select></label><label>{{en?'Creative tab':'游戏分类页'}}<select v-model="tab" @change="page=1"><option value="">{{en?'All tabs':'全部分类页'}}</option><option v-for="t in catalog?.tabs??[]" :key="t.id" :value="t.id">{{nameOf(t,lang)}}</option></select></label><label><input v-model="internal" type="checkbox" @change="page=1">{{en?'Internal items':'内部物品'}}</label><label class="vanilla-toggle"><input v-model="vanilla" type="checkbox" @change="page=1">{{en?'Include vanilla items':'包含原版物品'}}</label></div><p class="catalog-count" aria-live="polite">{{catalog?filtered.length:(en?'Loading…':'正在加载…')}} {{catalog?(en?'matching entries':'项内容'):''}} <span v-if="catalog">· MC {{catalog.minecraft}} · {{catalog.version}}</span></p><div class="catalog-grid"><button v-for="item in shown" :key="item.id" class="catalog-tile" @click="openItem(item.id)"><ModelPreview :url="item.model" :size="72" :label="nameOf(item,lang)"/><strong>{{nameOf(item,lang)}}</strong><span>{{item.internal?(en?'Internal / debug':'界面 / 调试'):categoryNames[lc][item.category]}}</span><code>{{item.id}}</code></button></div><p v-if="catalog&&!filtered.length">{{en?'No matches. Try an item ID or a shorter name.':'没有找到，试试物品 ID 或更短的关键词。'}}</p><nav class="catalog-pagination" :aria-label="en?'Catalog pages':'图鉴分页'"><button :disabled="page===1" @click="page--">{{en?'Previous':'上一页'}}</button><span>{{page}} / {{pages}}</span><button :disabled="page>=pages" @click="page++">{{en?'Next':'下一页'}}</button></nav><p v-if="error" role="alert">{{error}}</p></section></template>
<script setup lang="ts">
import{ref,computed,onMounted,watch}from'vue';import{useData}from'vitepress';import{getData,nameOf,locale,categoryNames,openItem}from'../lib/wiki';import ModelPreview from'./ModelPreview.vue';
const props=withDefaults(defineProps<{category?:string;tab?:string}>(),{category:'all',tab:''});const{lang}=useData();const lc=computed(()=>locale(lang.value)),en=computed(()=>lc.value==='en');const catalog=ref<any>(null),search=ref(''),filter=ref(props.category),tab=ref(props.tab),vanilla=ref(false),internal=ref(false),page=ref(1),error=ref('');const categories=Object.keys(categoryNames.zh).filter(k=>k!=='all');
const filtered=computed(()=>{const q=search.value.trim().toLocaleLowerCase();return Object.values(catalog.value?.items??{}).filter((i:any)=>(vanilla.value||i.id.startsWith('reverie_dreams:'))&&(internal.value||!i.internal)&&(filter.value==='all'||i.category===filter.value)&&(!tab.value||i.tabs.some((t:string)=>t.includes(tab.value)))&&(!q||[i.id,i.nameZh,i.nameEn,...i.descriptions.zh,...i.descriptions.en].join(' ').toLocaleLowerCase().includes(q))).sort((a:any,b:any)=>nameOf(a,lang.value).localeCompare(nameOf(b,lang.value),lang.value)) as any[]});const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/36))),shown=computed(()=>filtered.value.slice((page.value-1)*36,page.value*36));watch(pages,()=>page.value=Math.min(page.value,pages.value));
onMounted(async()=>{search.value=new URLSearchParams(location.search).get('search')??'';try{catalog.value=await getData()}catch{error.value=en.value?'Unable to load catalog. Reload this page.':'图鉴数据加载失败，请刷新页面。'}});
</script>
